import{_ as r,c as a,o as t,ag as o}from"./chunks/framework.Vyheyqg9.js";const m=JSON.parse('{"title":"Node.js Standard Library — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-02-standard-library.md","filePath":"practice/node-js/module-02-standard-library.md"}'),s={name:"practice/node-js/module-02-standard-library.md"};function n(i,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="node-js-standard-library-—-practice" tabindex="-1">Node.js Standard Library — practice <a class="header-anchor" href="#node-js-standard-library-—-practice" aria-label="Permalink to “Node.js Standard Library — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-02-standard-library.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h3 id="diagnostic-exercise" tabindex="-1"><span class="hub-section-number">1 </span>Diagnostic exercise <a class="header-anchor" href="#diagnostic-exercise" aria-label="Permalink to “1 Diagnostic exercise”">​</a></h3><p>Create a thumbnail-processing service with a fixed worker pool.</p><p>It must:</p><ul><li>reject work when its bounded queue is full;</li><li>cancel tasks whose caller disconnects;</li><li>replace a worker that crashes;</li><li>transfer image buffers where ownership permits;</li><li>expose queue depth and task duration;</li><li>stop accepting work and terminate workers during shutdown.</li></ul><hr><h2 id="_13-final-review-checklist" tabindex="-1"><span class="hub-section-number">2 </span>Final review checklist <a class="header-anchor" href="#_13-final-review-checklist" aria-label="Permalink to “2 Final review checklist”">​</a></h2><p>You should be able to explain and demonstrate each item without looking it up:</p><ul><li>Avoid shell injection by separating executable names from argument arrays.</li><li>Bound child-process runtime and output, and interpret exit code versus signal.</li><li>Design a worker pool with a bounded queue, cancellation, and crash replacement.</li><li>Explain copying, transferring, and sharing binary memory between workers.</li><li>Identify and close the owner of every timer, handle, child, worker, and socket.</li><li>Read positional arguments with <code>process.argv.slice(2)</code> and named options with <code>parseArgs()</code>.</li><li>Parse <code>process.env</code> values instead of treating them as typed configuration.</li><li>Keep results on stdout and errors on stderr.</li><li>Prefer <code>process.exitCode</code> when pending work should finish.</li><li>Distinguish operational failures from programmer bugs.</li><li>Match errors to synchronous throws, promise rejections, callback errors, or <code>&#39;error&#39;</code> events.</li><li>Know when <code>readFile()</code> returns a <code>Buffer</code> versus a string.</li><li>Use promise-based <code>fs</code> methods and understand when streams are more appropriate.</li><li>Sort directory entries whenever deterministic order matters.</li><li>Use <code>path.join()</code> for composition and <code>path.resolve()</code> for an absolute result.</li><li>Distinguish <code>process.cwd()</code> from the current module&#39;s directory.</li><li>Use SHA-256 for integrity checks, not password storage.</li><li>Use <code>randomBytes()</code> or <code>randomUUID()</code> when unpredictability matters.</li><li>Choose <code>exec</code>, <code>execFile</code>, <code>spawn</code>, or <code>fork</code> based on shell, buffering, streaming, and IPC needs.</li><li>Use cluster for multiple server processes and worker threads for CPU-heavy JavaScript.</li><li>Remember that cluster workers have separate process memory and worker threads only share memory explicitly.</li><li>Handle child and worker startup errors as well as non-zero exits.</li></ul><h2 id="_14-boundary-and-ownership-labs" tabindex="-1"><span class="hub-section-number">3 </span>Boundary and ownership labs <a class="header-anchor" href="#_14-boundary-and-ownership-labs" aria-label="Permalink to “3 Boundary and ownership labs”">​</a></h2><p>Baselines: Node24.18.0 runtime and TypeScript5.9.3 for isolated type checks; official Node24 API contracts checked2026-10-21. Use scratch fixtures and temporary app-owned directories, not production paths.</p><p><strong>Filesystem acceptance:</strong> create a normal child, a valid <code>..notes</code> child, a lexical ../ escape and a symlink to an external scratch file. Assert the first two resolve and the latter two reject; absolute/missing/empty paths follow the documented contract. Explain why a deliberately swapped ancestor after resolution is still a race and why the helper requires an untrusted-writer-free tree. Test Windows separately. Do not claim a traversal-resistant OS sandbox from this check.</p><p><strong>Fingerprint acceptance:</strong> compare the formerly ambiguous arrays <code>[&#39;a,b&#39;,&#39;c&#39;]</code> and <code>[&#39;a&#39;,&#39;b,c&#39;]</code> and require different digests. Input permutation produces the same digest, caller arrays are not mutated, empty/Unicode names are encoded deterministically, and content changes alone do not affect a names-only digest. If content integrity is required, design and version a separate canonical entry/content format.</p><p><strong>Error-boundary acceptance:</strong> a plain Error must not pass the code guard; an Error with a numeric code must fail; an Error with a string code passes. Unknown cannot authorize code/path access before checks. A nonempty configured signing secret must be narrowed before HMAC creation, not asserted present. These tests do not implement the full raw-body/timestamp/replay-safe webhook protocol, which is a separate lesson.</p><p><strong>Worker acceptance:</strong> write real workers for a valid result, invalid result, duplicate messages, immediate exit0, nonzero exit, thrown exception, message then live interval, and no-result live interval. Require exactly one selected outcome, exit0/no-message rejection, bounded deadline/caller abort behavior, no callbacks after cleanup and natural test-process termination. Pre-aborted signals must not start a worker; uncloneable input and invalid filename must reject. Confirm the parser protects result shape rather than casting unknown to TResult. A worker pool&#39;s queue/capacity/replace/drain implementation remains a separate practice task; this lab repairs one owned task.</p><p>Material checks and learner practice are separate. Record commands, Node version, fixtures, observations and any platform limitations. No user practice or production readiness follows from reading these examples.</p><p>Official references: <a href="https://nodejs.org/docs/latest-v24.x/api/worker_threads.html" target="_blank" rel="noreferrer">Node24 workers and termination</a>, <a href="https://nodejs.org/docs/latest-v24.x/api/path.html#pathrelativefrom-to" target="_blank" rel="noreferrer">Node24 path.relative</a>, <a href="https://nodejs.org/docs/latest-v24.x/api/fs.html" target="_blank" rel="noreferrer">Node24 realpath/file APIs</a>, <a href="https://nodejs.org/docs/latest-v24.x/api/crypto.html" target="_blank" rel="noreferrer">Node24 crypto</a>, <a href="https://community.owasp.org/attacks/Path_Traversal" target="_blank" rel="noreferrer">OWASP path traversal</a>, <a href="https://community.owasp.org/pages/vulnerabilities/race_conditions" target="_blank" rel="noreferrer">OWASP race conditions</a>.</p>',19)])])}const u=r(s,[["render",n]]);export{m as __pageData,u as default};
